## Code-Beispiele

### Beispiel 1: Basis-Tabelle mit TypeScript

Minimale typsichere Implementierung ohne optionale Features.

```tsx
import { DataTable, Column } from '@company/design-system';

interface Product {
  id: number;
  name: string;
  price: number;
  inStock: boolean;
}

// Column-Typ ist an Product gebunden – falsche keys werden von TypeScript abgelehnt
const columns: Column<Product>[] = [
  { 
    key: 'name',    // ✅ TypeScript-validiert: keyof Product
    header: 'Produkt' 
  },
  { 
    key: 'price', 
    header: 'Preis',
    render: (value) => `€ ${(value as number).toFixed(2)}`
  },
  { 
    key: 'inStock', 
    header: 'Verfügbarkeit',
    render: (value) => (
      <Badge variant={value ? 'success' : 'error'}>
        {value ? 'Auf Lager' : 'Ausverkauft'}
      </Badge>
    )
  },
];

export function ProductList({ products }: { products: Product[] }) {
  return (
    <DataTable<Product>
      data={products}
      columns={columns}
      striped
      emptyState={
        <EmptyState 
          icon={<BoxIcon />} 
          message="Keine Produkte gefunden" 
        />
      }
    />
  );
}
```

