### Beispiel 2: Sortierung, Pagination und Row-Interaction

Vollständiges Beispiel mit allen interaktiven Features.

```tsx
import { useState } from 'react';
import { DataTable, Column } from '@company/design-system';
import { useNavigate } from 'react-router-dom';

interface Order {
  id: string;
  customer: string;
  total: number;
  status: 'pending' | 'shipped' | 'delivered';
  createdAt: Date;
}

const columns: Column<Order>[] = [
  { key: 'id', header: 'Bestell-Nr.', width: 120 },
  { key: 'customer', header: 'Kunde' },
  { 
    key: 'total', 
    header: 'Betrag',
    width: '10%',
    render: (value) => `€ ${(value as number).toFixed(2)}`
  },
  { 
    key: 'status', 
    header: 'Status',
    render: (value) => <StatusBadge status={value as Order['status']} />
  },
  { 
    key: 'createdAt', 
    header: 'Datum',
    // Aktions-Spalten vom Sorting ausschließen
    sortable: false,
    render: (value) => (value as Date).toLocaleDateString('de-DE')
  },
];

export function OrderTable() {
  const navigate = useNavigate();
  const { data, isLoading } = useOrders();

  return (
    <DataTable<Order>
      data={data ?? []}
      columns={columns}
      loading={isLoading}
      sortable          // Aktiviert Sorting für alle Spalten (außer createdAt)
      pagination
      pageSize={25}
      stickyHeader
      onRowClick={(order) => navigate(`/orders/${order.id}`)}
      emptyState={<p>Noch keine Bestellungen vorhanden.</p>}
    />
  );
}
```

